                elementConfig: {
                    placeholder: 'Select the type of data...',
                    options: [
                        {value: 'BAM-FILE', displayValue: 'BAM-FILE'},
                        {value: 'VCF', displayValue: 'VCF'}
                    ]
                },
                value: ''
